self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE).then((c) => c.addAll(FILES)).then(() => self.skipWaiting())
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(
        keys.filter((k) => k.startsWith('doi-') && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

// Flutter fetches fallback fonts (e.g. Chinese, emoji) from Google Fonts
// the first time they're needed; keep those too.
function cacheable(url) {
  return url.origin === self.location.origin ||
    url.hostname.endsWith('gstatic.com') || url.hostname.endsWith('googleapis.com');
}

// Sent by index.html: files the page loaded before this worker was running.
self.addEventListener('message', (event) => {
  if (!event.data || event.data.type !== 'cache-loaded') return;
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    for (const u of event.data.urls || []) {
      try {
        const url = new URL(u);
        if (!cacheable(url) || url.pathname.endsWith('sw.js')) continue;
        if (await cache.match(u, { ignoreSearch: true })) continue;
        const res = await fetch(u);
        if (res.ok) await cache.put(u, res);
      } catch (e) {}
    }
  })());
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  const sameOrigin = url.origin === self.location.origin;
  if (!cacheable(url)) return;

  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const key = req.mode === 'navigate' ? './' : req;
    const cached = await cache.match(key, { ignoreSearch: sameOrigin });
    if (cached) return cached;
    try {
      const res = await fetch(req);
      if (res.ok || res.type === 'opaque') cache.put(key, res.clone());
      return res;
    } catch (e) {
      return (await cache.match('./')) || Response.error();
    }
  })());
});
